            aIngress = (RotL64(aWaterLaneA[((aIndex + 14174U)) & S_BLOCK1], 29U) ^ RotL64(aWindLaneC[((aIndex + 11904U)) & S_BLOCK1], 4U));
            aIngress ^= (RotL64(aEarthLaneA[((aIndex + 15802U)) & S_BLOCK1], 19U) ^ RotL64(aFireLaneB[((S_BLOCK1 - aIndex + 12818U)) & S_BLOCK1], 57U));
            aIngress = TwistMix64::DiffuseA(((aIngress ^ aDomainWordIngress) ^ aNonceWordM));
