            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aCarry, 57U) ^ RotL64(aIngress, 29U)) + (RotL64(aCross, 11U) + RotL64(aPrevious, 42U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterI = ((aWandererD + RotL64(aPrevious, 53U)) + 0x2CC72F970B4DDD97ULL) + aPhaseBOrbiterAssignSaltD[((aIndex + 9U)) & S_SALT1];
            aOrbiterD = (((aWandererG + RotL64(aCross, 13U)) + RotL64(aCarry, 5U)) + 0xBB82C46D68B8696FULL) + aPhaseBOrbiterAssignSaltE[((aIndex + 19U)) & S_SALT1];
            aOrbiterH = ((aWandererK + RotL64(aIngress, 29U)) + RotL64(aCarry, 23U)) + 0x89534330FCD744ECULL;
