            aOrbiterE = ((aWandererF + RotL64(aScatter, 21U)) + RotL64(aCarry, 53U)) + 0x54B33D34954468E9ULL;
            aOrbiterA = (aWandererJ + RotL64(aPrevious, 60U)) + 0x0AF8A44DCD199715ULL;
            //
            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0xA4AEFC09E1437141ULL) + aPhaseBOrbiterUpdateSaltD[((aIndex + 5U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0xBAB5B0F5B56982E0ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xE9B243BF99F4E33DULL), 11U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x9AB9EA8F71BCBDE6ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x946855375AAB0465ULL;
