            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x235662B1039CFAE9ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0xE26DE8A2E5A28C58ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xACCEBD8381CB5AC7ULL), 21U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x5BFB7BE69D8693B2ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x8C47ED02911B9D94ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x27A0C4E8A073595DULL), 47U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0xA89AD537548C62E0ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterD) ^ 0x31875C1A902FE6A7ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xEE20B75272EAC0F9ULL), 27U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterI) + 0x58BF76A333249919ULL) + aPhaseBOrbiterUpdateSaltB[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterA) ^ 0xBE22F8474E5E14B2ULL) ^ aPhaseBOrbiterUpdateSaltC[((aIndex + 11U)) & S_SALT1];
