            aOrbiterE = RotL64((aOrbiterE * 0x8177C1E050CDD0FBULL), 57U);
            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterG, 60U);
            aIngress = aIngress + (aOrbiterH ^ RotL64(aOrbiterE, 35U));
            aIngress = aIngress + (RotL64(aOrbiterB, 5U) ^ aOrbiterI);
