            aOrbiterD = (((aWandererG + RotL64(aPrevious, 27U)) + RotL64(aCarry, 35U)) + 0x7504920CCF568330ULL) + aPhaseCOrbiterAssignSaltA[((aIndex + 22U)) & S_SALT1];
            aOrbiterK = ((aWandererB + RotL64(aCross, 11U)) + RotL64(aCarry, 23U)) + 0xCD799A578ECE6436ULL;
