            //
            aOrbiterH = ((aOrbiterH + aOrbiterC) + 0xB21BF9C2FBA2F264ULL) + aPhaseCOrbiterUpdateSaltA[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0x6FC57A5CF3CE1B66ULL;
